  "Follow saves this account on this device. Add it to feeds.config.json and sync before its posts join the home timeline.": "फ़ॉलो करने से यह अकाउंट इस डिवाइस पर सेव हो जाता है। इसकी पोस्ट होम टाइमलाइन में आने से पहले इसे feeds.config.json में जोड़कर सिंक करें।",
