  "Save this account number. You can sign in with a passkey later. The number is an optional backup.": "यह अकाउंट नंबर सेव कर लें। बाद में आप पासकी से साइन इन कर सकते हैं। यह नंबर एक वैकल्पिक बैकअप है।",
