  "Summary": "सारांश",
  "This stays on this device. Translation is not available offline yet.": "यह इसी डिवाइस पर रहता है। अनुवाद अभी ऑफ़लाइन उपलब्ध नहीं है।",
  "This stays on this device. A summary is not available offline yet.": "यह इसी डिवाइस पर रहता है। सारांश अभी ऑफ़लाइन उपलब्ध नहीं है।",
