  "Keep it for good. You get an account number and recovery codes to sign in on other devices.": "इसे हमेशा के लिए रखें। दूसरे डिवाइस पर साइन इन के लिए आपको अकाउंट नंबर और रिकवरी कोड मिलेंगे।",
